#include "data_loader.hpp"
#include "experiment_engine.hpp"
#include "extended_features.hpp"
#include <algorithm>
#include <cmath>
#include <cstdlib>
#include <iomanip>
#include <iostream>
#include <vector>

static void addBias(std::vector<double>& p,int cls,double b){double z[3],mx=-1e300,s=0;for(int c=0;c<3;++c){z[c]=std::log(std::max(1e-12,p[c]))+(c==cls?b:0);mx=std::max(mx,z[c]);}for(int c=0;c<3;++c){p[c]=std::exp(z[c]-mx);s+=p[c];}for(double&v:p)v/=s;}
static void score(msar::RepeatedCVResult&r){const std::vector<double>w={1,1,1};r.acc_mean=r.macro_f1_mean=r.log_loss_mean=0;for(auto&f:r.folds){std::vector<int>pred(f.fold_labels.size(),0);for(size_t i=0;i<pred.size();++i){if(f.fold_probabilities[i][1]>f.fold_probabilities[i][pred[i]])pred[i]=1;if(f.fold_probabilities[i][2]>f.fold_probabilities[i][pred[i]])pred[i]=2;}f.eval_res=msar::evaluatePredictions(f.fold_labels,pred,f.fold_probabilities,w);f.accuracy=f.eval_res.accuracy;f.macro_f1=f.eval_res.macro_f1;f.log_loss=f.eval_res.weighted_loss;r.acc_mean+=f.accuracy;r.macro_f1_mean+=f.macro_f1;r.log_loss_mean+=f.log_loss;}double n=r.folds.size();r.acc_mean/=n;r.macro_f1_mean/=n;r.log_loss_mean/=n;}
static msar::RepeatedCVResult blendSchedulesRaw(const msar::RepeatedCVResult&a,const msar::RepeatedCVResult&b){msar::RepeatedCVResult out=a;for(size_t f=0;f<out.folds.size();++f)for(size_t i=0;i<out.folds[f].fold_probabilities.size();++i)for(int c=0;c<3;++c)out.folds[f].fold_probabilities[i][c]=0.5*(a.folds[f].fold_probabilities[i][c]+b.folds[f].fold_probabilities[i][c]);score(out);return out;}
static msar::RepeatedCVResult applyFinalCalibration(const msar::RepeatedCVResult&raw,const std::vector<msar::GapRecord>&data,const std::vector<unsigned int>&seeds){msar::RepeatedCVResult out=raw;size_t fi=0;for(unsigned int seed:seeds){const auto folds=msar::createStratifiedFolds(data,5,seed);for(size_t f=0;f<folds.size();++f,++fi)for(size_t i=0;i<out.folds[fi].fold_probabilities.size();++i){auto&p=out.folds[fi].fold_probabilities[i];addBias(p,2,-0.10);const auto&rec=data[folds[f].val_indices[i]];if(msar::toLowerString(rec.pronoun)=="him"){const long long da=std::llabs(rec.pronoun_offset-rec.a_offset),db=std::llabs(rec.pronoun_offset-rec.b_offset);if(da<db)addBias(p,0,-0.10);else if(db<da)addBias(p,1,-0.10);}}}score(out);return out;}
static msar::RepeatedCVResult mixThenCalibrate(const msar::RepeatedCVResult&base,const msar::RepeatedCVResult&candidate,double weight,const std::vector<msar::GapRecord>&data,const std::vector<unsigned int>&seeds){msar::RepeatedCVResult out=base;for(size_t f=0;f<out.folds.size();++f)for(size_t i=0;i<out.folds[f].fold_probabilities.size();++i)for(int c=0;c<3;++c)out.folds[f].fold_probabilities[i][c]=(1.0-weight)*base.folds[f].fold_probabilities[i][c]+weight*candidate.folds[f].fold_probabilities[i][c];return applyFinalCalibration(out,data,seeds);}
static std::pair<msar::RepeatedCVResult,msar::RepeatedCVResult> runSchedules(const std::vector<msar::GapRecord>&data,msar::ExtendedConfig features,const std::vector<unsigned int>&seeds,const std::string&name){msar::ExperimentConfig cfg;cfg.name=name;cfg.feature_dim=features.getTotalDimension();cfg.hidden_dim=32;cfg.output_dim=3;cfg.learning_rate=0.0012;cfg.class_weight_alpha=0.24;cfg.l2_lambda=0.0001;cfg.batch_size=32;cfg.max_epochs=20;cfg.use_swap_aug=true;cfg.use_tta=true;cfg.use_swa=true;cfg.swa_epochs=5;cfg.ensemble_members=10;cfg.use_cosine_lr=false;auto constant=msar::runRepeatedCVExtended(data,features,cfg,seeds);cfg.use_cosine_lr=true;auto cosine=msar::runRepeatedCVExtended(data,features,cfg,seeds);return {constant,cosine};}
int main(){const auto dev=msar::loadGapDataset("data/raw/gap-development.tsv");const auto val=msar::loadGapDataset("data/raw/gap-validation.tsv");std::vector<msar::GapRecord>data=dev;data.insert(data.end(),val.begin(),val.end());const std::vector<unsigned int>seeds={11100,11101,11102};
 msar::ExtendedConfig base_features;base_features.use_url=true;base_features.use_syntax=true;base_features.use_v2x_matcher=true;auto base_pair=runSchedules(data,base_features,seeds,"fixed20_local_tfidf_exact_order_grid_base");auto base_raw=blendSchedulesRaw(base_pair.first,base_pair.second);auto base=applyFinalCalibration(base_raw,data,seeds);
 msar::ExtendedConfig candidate_features=base_features;candidate_features.use_local_tfidf_overlap=true;auto candidate_pair=runSchedules(data,candidate_features,seeds,"fixed20_local_tfidf_exact_order_grid_candidate");auto candidate_raw=blendSchedulesRaw(candidate_pair.first,candidate_pair.second);
 std::cout<<std::fixed<<std::setprecision(6)<<"N="<<data.size()<<" seeds=11100,11101,11102 folds=15 test_loaded=no; inference-order calibration\n"<<"base,"<<base.acc_mean<<','<<base.macro_f1_mean<<','<<base.log_loss_mean<<'\n';
 for(double w:{0.25,0.50,0.75,1.00}){const auto blended=mixThenCalibrate(base_raw,candidate_raw,w,data,seeds);const auto paired=msar::comparePaired(base,blended);std::cout<<"local_tfidf_weight_"<<w<<','<<blended.acc_mean<<','<<blended.macro_f1_mean<<','<<blended.log_loss_mean<<','<<paired.mean_loss_diff<<','<<paired.se_loss_diff<<','<<paired.delta_accuracy<<','<<blended.macro_f1_mean-base.macro_f1_mean<<','<<(paired.accepted?"yes":"no")<<'\n';}return 0;}
